    studentOrder(data) {
        
        let female = data.filter(v => v.gender == '2');
        
        let ts = female.sort((a, b) => {
          let fa = a.name.toLowerCase(),
            fb = b.name.toLowerCase();
    
          if (fa < fb) {
            return -1;
          }
          if (fa > fb) {
            return 1;
          }
          return 0;
        });
        
        let male = data.filter(v => v.gender == '1');
        male.sort((a, b) => {
          let fa = a.name.toLowerCase(),
            fb = b.name.toLowerCase();
    
          if (fa < fb) {
            return -1;
          }
          if (fa > fb) {
            return 1;
          }
          return 0;
        });
        
        let newll = female.concat(male);
        
        return newll
      }


